function flipVowels(s: string): string {
  const isVowel = (c: string) => "aeiouAEIOU".includes(c);
  const vowels = [...s].filter(isVowel);
  return [...s].map(c => (isVowel(c) ? vowels.pop()! : c)).join("");
}

