function flipVowels(s: string): string {
  const VOWELS = new Set("aeiouAEIOU");
  const a = s.split("");
  let lo = 0, hi = a.length - 1;
  while (lo < hi) {
    while (lo < hi && !VOWELS.has(a[lo])) lo++;
    while (lo < hi && !VOWELS.has(a[hi])) hi--;
    [a[lo], a[hi]] = [a[hi], a[lo]];
    lo++;
    hi--;
  }
  return a.join("");
}

