class Solution:
    def flipVowels(self, s: str) -> str:
        vowels = set("aeiouAEIOU")
        a = list(s)
        lo, hi = 0, len(a) - 1
        while lo < hi:
            while lo < hi and a[lo] not in vowels:
                lo += 1
            while lo < hi and a[hi] not in vowels:
                hi -= 1
            a[lo], a[hi] = a[hi], a[lo]
            lo += 1
            hi -= 1
        return "".join(a)

